def solve_pairing(n):
    """
    Checks if the set {1, ..., 2n} can be partitioned into n pairs 
    with differences {1, ..., n}.
    """
    numbers = list(range(1, 2 * n + 1))
    required_diffs = set(range(1, n + 1))

    # State: remaining numbers (used for matching) and remaining required differences

    def backtrack(remaining_numbers, remaining_diffs):
        if not remaining_numbers:
            return True

        # Pick the smallest remaining number, s
        s = min(remaining_numbers)

        # Try pairing s with every other remaining number t
        for i, t in enumerate(remaining_numbers):
            if s == t:
                continue

            diff = abs(s - t)

            if diff in remaining_diffs:
                # Potential pairing (s, t) found

                # Update states
                new_remaining_numbers = remaining_numbers[:i] + remaining_numbers[i+1:]
                new_remaining_diffs = remaining_diffs - {diff}

                # Recursive call
                if backtrack(new_remaining_numbers, new_remaining_diffs):
                    return True

        return False

    return backtrack(numbers, required_diffs)

test_cases = [3, 4, 5]
results = {}
for n in test_cases:
    results[n] = solve_pairing(n)

print("Test results for small n:")
for n, exists in results.items():
    print(f"n={n}: Exists? {exists}")
